function validate([message, bannedWords]) {
  for (const [name, list] of [['message', message], ['bannedWords', bannedWords]]) {
    if (!Array.isArray(list) || list.length < 1 || list.length > 100000) return `${name} needs 1 to 10^5 words.`;
    if (list.some(w => typeof w !== 'string' || !/^[a-z]{1,15}$/.test(w))) return `Each word of ${name} has 1 to 15 lowercase letters.`;
  }
  return null;
}

