function reportSpam(message, bannedWords) {
  // Compare every entry with every banned word, then count the entries that matched at least once.
  let matches = 0;
  for (let i = 0; i < message.length; i++) {
    let found = false;
    for (let j = 0; j < bannedWords.length; j++) if (message[i] === bannedWords[j]) found = true;
    if (found) matches++;
  }
  return matches >= 2;
}

