function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const word = (letters, min, max) => Array.from({ length: int(min, max) }, () => letters[int(0, letters.length - 1)]).join('');
  const all = 'abcdefghijklmnopqrstuvwxyz';
  if (size === 'small') {
    // Tiny words over two or three letters make matches, repeats and near-misses common.
    const letters = rand() < 0.7 ? 'ab' : 'abc';
    const message = Array.from({ length: int(1, 6) }, () => word(letters, 1, 2));
    const bannedWords = Array.from({ length: int(1, 6) }, () => word(letters, 1, 2));
    return [message, bannedWords];
  }
  const shape = Math.floor(rand() * 3);
  if (shape === 0) {
    // A shared vocabulary of short words: most entries are banned.
    const pool = Array.from({ length: 300 }, () => word(all, 1, 4));
    const pick = () => pool[int(0, pool.length - 1)];
    return [Array.from({ length: int(1500, 2000) }, pick), Array.from({ length: int(1500, 2000) }, pick)];
  }
  // Banned words start with a-m and message words with n-z, then exactly one or two banned words are planted.
  const bannedWords = Array.from({ length: int(1500, 2000) }, () => word('abcdefghijklm', 1, 1) + word(all, 0, 14));
  const message = Array.from({ length: int(1500, 2000) }, () => word('nopqrstuvwxyz', 1, 1) + word(all, 0, 14));
  const first = int(0, message.length - 1);
  message[first] = bannedWords[int(0, bannedWords.length - 1)];
  if (shape === 2) message[(first + int(1, message.length - 1)) % message.length] = bannedWords[int(0, bannedWords.length - 1)];
  return [message, bannedWords];
}
